import{_ as a,o,c as r,ag as t}from"./chunks/framework.DJVIMu25.js";const f=JSON.parse('{"title":"Data Storage","description":"","frontmatter":{"title":"Data Storage"},"headers":[],"relativePath":"en/reference/storage.md","filePath":"en/reference/storage.md","lastUpdated":1786545590000}'),s={name:"en/reference/storage.md"};function i(n,e,d,l,c,m){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="data-storage" tabindex="-1">Data Storage <a class="header-anchor" href="#data-storage" aria-label="Permalink to &quot;Data Storage&quot;">​</a></h1><p>JoyMart provides two storage backends: YAML files (default, single server) and MySQL (recommended for cross-server). The storage mode is configured in the <code>storage</code> block of <code>config.yml</code> — see <a href="./../guides/configuration#config-yml">Configuration Files</a>.</p><h2 id="yaml-default-single-server" tabindex="-1">YAML (default, single server) <a class="header-anchor" href="#yaml-default-single-server" aria-label="Permalink to &quot;YAML (default, single server)&quot;">​</a></h2><ul><li>Player data: <code>plugins/JoyMart/data/players/&lt;uuid&gt;.yml</code></li><li>High scores: <code>plugins/JoyMart/data/scores/&lt;gameId&gt;.yml</code></li></ul><h2 id="mysql-recommended-for-cross-server" tabindex="-1">MySQL (recommended for cross-server) <a class="header-anchor" href="#mysql-recommended-for-cross-server" aria-label="Permalink to &quot;MySQL (recommended for cross-server)&quot;">​</a></h2><p>Enable <code>mysql.enabled: true</code> in <code>config.yml</code> and fill in the connection details. JoyMart automatically manages connections via a HikariCP connection pool; all BungeeCord sub-servers share the same high-score table and token data.</p><h2 id="data-migration" tabindex="-1">Data Migration <a class="header-anchor" href="#data-migration" aria-label="Permalink to &quot;Data Migration&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Migration commands</p><p><code>/gba migrate mysql</code> imports existing YAML data into MySQL; <code>/gba migrate file</code> does the reverse.</p></div><p>The migration command requires the <code>gamebox.admin.migrate</code> permission — see <a href="./../guides/commands">Commands &amp; Permissions</a>.</p>',9)])])}const u=a(s,[["render",i]]);export{f as __pageData,u as default};
